fn main()->Result<(),String>{let args:Vec<_>=std::env::args().collect();let data=args.get(1).map(String::as_str).unwrap_or("data/ssq.csv");let root=args.get(2).map(String::as_str).unwrap_or("recommendations");let draws=ssq::draw::load_csv(std::path::Path::new(data))?;let report=ssq::prize_coverage::report(std::path::Path::new(root),&draws)?;println!("{}",serde_json::to_string_pretty(&report).map_err(|e|e.to_string())?);Ok(())}
